INSERT INTO public.products (id, shop_id, title, image, usd_price, original_usd_price, rating, review_count, category, province, in_stock, stock_count, description, features, specifications, badge_discount, badge_logistics, badge_logistics_text, is_active, is_demo) VALUES ('samsung-galaxy-a54-5g', 'kazi-tech', 'Smartphone Samsung Galaxy A54 5G 128Go', '/images/products/samsung-galaxy-a54-5g.jpg', 295, 390, 4.8, 84, 'Smartphones & Tablettes', 'Kinshasa', true, 28, NULL, '{}'::text[], '{}'::jsonb, '-25%', 'express', 'Kin Express', true, true) ON CONFLICT (id) DO UPDATE SET shop_id = EXCLUDED.shop_id, title = EXCLUDED.title, image = EXCLUDED.image, usd_price = EXCLUDED.usd_price, original_usd_price = EXCLUDED.original_usd_price, rating = EXCLUDED.rating, review_count = EXCLUDED.review_count, in_stock = EXCLUDED.in_stock, stock_count = EXCLUDED.stock_count, description = EXCLUDED.description, features = EXCLUDED.features, specifications = EXCLUDED.specifications, badge_discount = EXCLUDED.badge_discount, badge_logistics = EXCLUDED.badge_logistics, badge_logistics_text = EXCLUDED.badge_logistics_text, is_active = true, is_demo = true;
INSERT INTO public.products (id, shop_id, title, image, usd_price, original_usd_price, rating, review_count, category, province, in_stock, stock_count, description, features, specifications, badge_discount, badge_logistics, badge_logistics_text, is_active, is_demo) VALUES ('station-energie-solaire-1000w', 'solaris-rdc', 'Station d''Énergie Solaire Portable 1000W / 220V', '/images/products/station-energie-solaire-1000w.jpg', 640, 720, 4.9, 112, 'Énergie Solaire & Onduleurs', 'Kongo Central', true, 14, 'La Station d''Énergie Solaire Portable 1000W / 220V est la solution idéale pour pallier les délestages et coupures d''électricité fréquentes dans toutes les villes de la RDC. Dotée d''un onduleur pur sinus 220V et de cellules de batterie LiFePO4 ultra-durables (plus de 3 000 cycles de recharge), elle alimente sans interruption vos téléviseurs, ordinateurs, éclairages, ventilateurs, réfrigérateurs portables et matériels médicaux. Rechargeable sur prise secteur 220V, sur allume-cigare ou directement via panneaux solaires photovoltaïques (MPPT intégré).', '{"Puissance de sortie continue 1000W (crête à 2000W) – onde sinusoïdale pure 220V / 50Hz","Batterie LiFePO4 haute sécurité 1024Wh (durée de vie supérieure à 10 ans / 3000+ cycles)","Régulateur de charge solaire MPPT intégré acceptant jusqu'à 200W de panneaux solaires","Sorties polyvalentes : 2x prises AC 220V, 2x USB-C Power Delivery 100W, 2x USB-A Fast Charge, 1x DC 12V 10A","Écran LCD intelligent affichant le pourcentage de batterie, la puissance consommée et le temps restant","Protection intégrale contre les surtensions, courts-circuits et surchauffes climatiques"}'::text[], '{"Capacité batterie":"1024 Wh (320 000 mAh / 3.2V)","Chimie de cellule":"Lithium Fer Phosphate (LiFePO4)","Cycles de vie":"3 000+ cycles à 80% de capacité résiduelle","Sortie AC (x2)":"220V ~ 50Hz, 1000W continu (Crête 2000W), Onde sinusoïdale pure","Sortie USB-C (x2)":"5V/9V/12V/15V/20V, jusqu''à 5A (100W Max par port)","Sortie USB-A (x2)":"5V/3A, 9V/2A, 12V/1.5A (18W Max)","Sortie Allume-cigare":"12V / 10A (120W Max régulé)","Entrée de charge solaire":"Port DC5521 / XT60, 12V - 30V / 10A (200W Max MPPT)","Temps de recharge secteur":"Environ 1h30 à 80% sur courant 220V","Dimensions":"340 x 231 x 206 mm","Poids net":"11.2 kg avec poignée ergonomique","Garantie":"2 ans pièces et main d''œuvre certifié Mwinda"}'::jsonb, 'Top Vente', 'interprovincial', 'Solaire RDC', true, true) ON CONFLICT (id) DO UPDATE SET shop_id = EXCLUDED.shop_id, title = EXCLUDED.title, image = EXCLUDED.image, usd_price = EXCLUDED.usd_price, original_usd_price = EXCLUDED.original_usd_price, rating = EXCLUDED.rating, review_count = EXCLUDED.review_count, in_stock = EXCLUDED.in_stock, stock_count = EXCLUDED.stock_count, description = EXCLUDED.description, features = EXCLUDED.features, specifications = EXCLUDED.specifications, badge_discount = EXCLUDED.badge_discount, badge_logistics = EXCLUDED.badge_logistics, badge_logistics_text = EXCLUDED.badge_logistics_text, is_active = true, is_demo = true;
