INSERT INTO public.product_reviews (id, product_id, author, city, rating, review_date, comment, verified_purchase, is_demo) VALUES ('rev-1', 'station-energie-solaire-1000w', 'Dieudonné Mukendi', 'Kinshasa (Gombe)', 5, '14 Janvier 2025', 'Indispensable à Kinshasa ! La station fait tourner mon bureau à domicile (PC fixe, 2 écrans, box internet et ventilateur) pendant plus de 7 heures d''affilée sans aucune baisse de tension. Le pur sinus protège parfaitement le matériel électronique sensible.', true, true) ON CONFLICT (id) DO UPDATE SET author = EXCLUDED.author, rating = EXCLUDED.rating, comment = EXCLUDED.comment, is_demo = true;
INSERT INTO public.product_reviews (id, product_id, author, city, rating, review_date, comment, verified_purchase, is_demo) VALUES ('rev-2', 'station-energie-solaire-1000w', 'Grâce Tshilombo', 'Lubumbashi (Haut-Katanga)', 5, '03 Février 2025', 'Livrée à Lubumbashi en 48 heures via le hub Mwinda. Emballage très soigné et batterie chargée à 60% dès réception. Fonctionne à merveille avec 2 panneaux solaires de 100W.', true, true) ON CONFLICT (id) DO UPDATE SET author = EXCLUDED.author, rating = EXCLUDED.rating, comment = EXCLUDED.comment, is_demo = true;
INSERT INTO public.product_reviews (id, product_id, author, city, rating, review_date, comment, verified_purchase, is_demo) VALUES ('rev-3', 'station-energie-solaire-1000w', 'Dr. Patrick Kalambayi', 'Matadi (Kongo Central)', 5, '19 Février 2025', 'Achetée directement auprès de Solaris RDC ici à Matadi. Très silencieuse par rapport aux groupes électrogènes bruyants. C''est du matériel professionnel très robuste.', true, true) ON CONFLICT (id) DO UPDATE SET author = EXCLUDED.author, rating = EXCLUDED.rating, comment = EXCLUDED.comment, is_demo = true;
INSERT INTO public.product_reviews (id, product_id, author, city, rating, review_date, comment, verified_purchase, is_demo) VALUES ('rev-4', 'station-energie-solaire-1000w', 'Sifa Kabuo', 'Goma (Nord-Kivu)', 4, '28 Février 2025', 'Excellent produit, solide et facile à transporter avec la poignée. Petit bémol sur le poids (11kg) mais c''est normal pour une vraie batterie LiFePO4 de 1000Wh.', true, true) ON CONFLICT (id) DO UPDATE SET author = EXCLUDED.author, rating = EXCLUDED.rating, comment = EXCLUDED.comment, is_demo = true;